/*
 * A117999  Decimal number generated by the binary bits of the n-th generation
 *          of the Rule 110 elementary cellular automaton.
 * https://oeis.org/A117999
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   a(n) = A006978(n+1) * 2^n
 * Range:     u8 n <= 3, u16 n <= 7, u32 n <= 15, u64 n <= 31, u128 n <= 63,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computationally: simulate the Rule 110 elementary cellular automaton
   and interpret each generation as a binary number. */

#include <stdlib.h>
#include <stdint.h>

seq_t a(idx_t n)
{
    /* static state kept between calls */
    static uint8_t *cur = NULL;          /* bits of the current generation   */
    static size_t   cur_len = 0;          /* its length                       */
    static seq_t  *cache = NULL;          /* cached decimal values            */
    static idx_t   cache_size = 0;        /* number of cached terms           */

    /* Rule 110 transition table: index = (left<<2)|(center<<1)|right   */
    static const uint8_t rule110[8] =
    {
        /* 000 001 010 011 100 101 110 111 */
        0, 1, 1, 1, 0, 1, 1, 0
    };

    /* Initialise state on first call */
    if (cur == NULL)
    {
        cur_len = 1;
        cur = (uint8_t *)malloc(cur_len * sizeof(uint8_t));
        if (!cur) abort();
        cur[0] = 1;                 /* a(0) = 1 */

        cache = (seq_t *)malloc(sizeof(seq_t));
        if (!cache) abort();
        cache[0] = (seq_t)1;
        cache_size = 1;
    }

    /* If we already have the requested term, return it */
    if (n < cache_size)
        return cache[n];

    /* Compute generations from the last cached one up to n */
    for (idx_t step = cache_size; step <= n; ++step)
    {
        size_t new_len = cur_len + 2;            /* Rule 110 expands by 2 cells each step */
        uint8_t *next_row = (uint8_t *)malloc(new_len * sizeof(uint8_t));
        if (!next_row) abort();

        /* Compute the new generation */
        for (size_t i = 0; i < new_len; ++i)
        {
            uint8_t lc = 0, mc = 0, rc = 0;
            if (i >= 2 && (i - 2) < cur_len) lc = cur[i - 2];
            if (i >= 1 && (i - 1) < cur_len) mc = cur[i - 1];
            if (i < cur_len)                   rc = cur[i];
            uint8_t idx = (lc << 2) | (mc << 1) | rc;
            next_row[i] = rule110[idx];
        }

        /* Interpret the bits of next_row as a binary number */
        seq_t val = (seq_t)0;
        for (size_t i = 0; i < new_len; ++i)
            val = (val << 1) + (seq_t)next_row[i];

        /* Store the new value into the cache */
        seq_t *tmp = (seq_t *)realloc(cache,
                                      (step + 1) * sizeof(seq_t));
        if (!tmp) abort();
        cache = tmp;
        cache[step] = val;

        /* Advance the current row to the newly computed one */
        free(cur);
        cur = next_row;
        cur_len = new_len;

        /* Update the cache size to reflect the new entry */
        cache_size = step + 1;
    }

    return cache[n];
}
